from fl_dsl import unit, S, q, concept, math, deeper, src

unit('PROTECT', 'Consumer Protection, Fraud, and Digital Security', ['17 Consumer Protection and Fraud'])

FTC_IDT = src('FTC (IdentityTheft.gov)', 'https://www.identitytheft.gov/', 'IdentityTheft.gov creates a personal recovery plan and an FTC Identity Theft Report.')
FTC_SCAMS = src('FTC (Scams)', 'https://consumer.ftc.gov/features/scam-alerts', 'Scammers pretend to be from trusted organizations, create urgency, and ask for payment by gift card, wire, cryptocurrency, or payment app.')
FTC_CHECK = src('FTC (Fake check scams)', 'https://consumer.ftc.gov/articles/how-spot-avoid-and-report-fake-check-scams', 'Banks must make deposited funds available quickly, but a fake check can bounce days later and the depositor must repay the bank.')
CFPB_EFTA = src('CFPB (Regulation E: lost or stolen debit cards)', 'https://www.consumerfinance.gov/ask-cfpb/how-do-i-get-my-money-back-after-a-debit-card-theft-en-1017/', 'Liability for unauthorized debit card use is limited to $50 if reported within 2 business days of learning of the loss, up to $500 if reported later, and can be unlimited if not reported within 60 days after the statement is sent.', eff='Regulation E as of 2026')
CFPB_CC = src('CFPB (Credit card fraud liability)', 'https://www.consumerfinance.gov/ask-cfpb/what-is-my-liability-for-unauthorized-credit-card-charges-en-24/', 'Under federal law, liability for unauthorized credit card charges is at most $50.')
CFPB_COMPLAINT = src('CFPB (Submit a complaint)', 'https://www.consumerfinance.gov/complaint/', 'Consumers can submit complaints about financial products; the CFPB forwards them to companies for a response.')
FTC_COOL = src('FTC (Cooling-Off Rule)', 'https://consumer.ftc.gov/articles/buyers-remorse-ftcs-cooling-rule-may-help', 'The Cooling-Off Rule gives buyers 3 days to cancel certain sales of $25 or more made at their home or at temporary locations.')
NJ_DCA = src('New Jersey Division of Consumer Affairs', 'https://www.njconsumeraffairs.gov/', 'New Jersey residents can file consumer complaints with the Division of Consumer Affairs, which enforces the New Jersey Consumer Fraud Act.')
CISA = src('CISA (Secure Our World)', 'https://www.cisa.gov/secure-our-world', 'Recommends strong passwords or a password manager, multifactor authentication, software updates, and recognizing phishing.')

# ---------------------------------------------------------------- S98
S(98, 'Identity theft: prevention and recovery', 'Recognize signs of identity theft and follow the steps to recover',
  main=[
    q('Rosa gets a bill for a credit card she never opened. What is the most likely explanation?', 'Someone used her identity',
      [('The bank sends random cards to everyone as a gift', 'Banks do not open accounts without applications'), ('Her credit score rose and a card opened by itself', 'Accounts do not open themselves'), ('It is a normal reminder to apply for a card', 'Misreads a bill as an offer')],
      intro='Identity theft is when someone uses your personal information, such as your name and Social Security number, to open accounts, file taxes, or get services. Signs include unfamiliar bills, accounts on your credit report, or calls from debt collectors about debts you do not owe.',
      fb='An unknown account is a key sign of identity theft.', sub='Signs of identity theft'),
    q('Which website gives a free, step-by-step recovery plan after identity theft?', 'IdentityTheft.gov',
      [('A company that charges to "erase" the theft', 'Paid services cannot do more than you can for free'), ('The thief\'s social media page', 'Not a recovery resource'), ('A random forum post', 'Not reliable')],
      intro='The Federal Trade Commission runs IdentityTheft.gov, which builds a recovery plan and an Identity Theft Report you can use with businesses and credit bureaus.',
      fb='IdentityTheft.gov is the free federal recovery site.', sub='Recovery plan', how=True),
    q('After discovering the fake account, which step should Rosa take early?', 'Freeze her credit at all three bureaus',
      [('Post her Social Security number to warn friends', 'Spreads the information further'), ('Wait a year to see if it happens again', 'Lets more damage happen'), ('Close her own savings account and keep cash at home', 'Does not stop the theft')],
      intro='A credit freeze blocks new credit in your name until you lift it. It is free at Equifax, Experian, and TransUnion. Also contact the business where the fraud happened and review your credit reports.',
      fb='A free freeze at each bureau stops new accounts.', sub='Freezing credit', how=True),
    q('Which habit best protects Rosa\'s Social Security number?', 'Sharing it only when truly required',
      [('Keeping her Social Security card in her wallet every day', 'Easy to lose or steal'), ('Writing it on forms that only ask for "ID"', 'Overshares'), ('Giving it to anyone who calls and says they are from a bank', 'Imposter risk')],
      fb='Share your SSN only when required and keep the card at home.', sub='Protecting your SSN'),
    q('A company says Rosa\'s data was exposed in a data breach. Which response helps most?', 'Change passwords and watch her accounts',
      [('Ignore it because breaches never affect individuals', 'Underestimates the risk'), ('Reply to the email with her full account numbers', 'Phishing risk'), ('Stop using every bank forever', 'Overreacts')],
      fb='After a breach, change passwords, use multifactor authentication, check statements, and consider a freeze.', sub='Data breaches', how=True),
  ],
  back=[
    concept('Personal information and why thieves want it', 'Protecting identity starts with knowing which information is valuable.', [
      q('Which information is most valuable to an identity thief?', 'A Social Security number',
        [('A favorite movie', 'Not identifying'), ('A shoe size', 'Not identifying'), ('The name of a school mascot', 'Not identifying')],
        fb='SSNs can open accounts and file taxes in your name.', sub='Sensitive information'),
      q('Where should a Social Security card usually be kept?', 'Somewhere safe at home',
        [('In a phone case', 'Easy to lose'), ('Taped inside a car', 'Easy to steal'), ('In a backpack every day', 'Easy to lose')],
        fb='Keep it in a safe place, not on you.', sub='Storing documents'),
      q('Which document should be shredded before throwing it out?', 'An old bank statement',
        [('A takeout menu', 'No personal data'), ('A blank sheet of paper', 'No data'), ('A store coupon', 'No personal data')],
        fb='Statements contain account numbers.', sub='Shredding'),
      q('How many major consumer credit bureaus are there?', '3',
        [('1', 'Undercounts'), ('5', 'Overcounts'), ('50', 'Confuses with states')],
        fb='Equifax, Experian, and TransUnion.', calc=3, sub='Credit bureaus'),
      q('How can Rosa spot an account she did not open?', 'Review her free credit reports',
        [('Check the likes on her social media posts', 'Unrelated'), ('Read her school schedule', 'Unrelated'), ('Count her cash', 'Unrelated')],
        fb='Credit reports list accounts in your name.', sub='Monitoring'),
    ]),
    math('Solve multistep problems with rational numbers', 'Losses and liability limits compare amounts step by step.', 'grade_7', 29),
  ],
  go=[
    deeper('Special cases of identity theft', [
      q('The IRS rejects Rosa\'s tax return because one was already filed with her SSN. What happened?', 'Tax identity theft',
        [('She filed twice by accident, which is normal', 'Misreads the warning'), ('Her employer filed her return for her', 'Employers do not file personal returns'), ('The IRS lost her return', 'Not what the rejection means')],
        intro='In tax identity theft, a thief files a return to steal a refund. The IRS offers an Identity Protection PIN to prevent it.',
        fb='A rejected return because one was already filed signals tax identity theft.', sub='Tax identity theft'),
      q('Why do thieves target children\'s identities?', 'Theft can go unnoticed for years',
        [('Children have high credit limits', 'They usually have no credit'), ('Children\'s SSNs expire at 18', 'Untrue'), ('Banks require children to have cards', 'Untrue')],
        intro='Parents can request a credit freeze for children under 16.',
        fb='Children rarely check credit, so theft can go unnoticed.', sub='Child identity theft'),
      q('Someone used Rosa\'s information to see a doctor. Which records might be wrong?', 'Her medical records',
        [('Her library card', 'Unrelated'), ('Her report card', 'Unrelated'), ('Her phone\'s wallpaper', 'Unrelated')],
        fb='Medical identity theft can put false information in medical records.', sub='Medical identity theft'),
      q('A thief made $2,400 of fraudulent charges on Rosa\'s credit card. Under federal law, what is the most she can be held liable for?', '$50',
        [('$2,400', 'Ignores the federal limit'), ('$500', 'Confuses with a debit card rule'), ('$1,200', 'Halves the charges')],
        intro='Federal law caps liability for unauthorized credit card charges at $50, and many issuers offer $0 liability.',
        fb='Liability is capped at $50.', calc=50, sub='Credit card liability', eff='Federal law as of 2026'),
      q('Rosa needs to apply for a car loan but has a freeze. What should she do?', 'Temporarily lift the freeze',
        [('Remove the freeze permanently forever', 'Not needed'), ('Apply under a friend\'s name', 'Fraud'), ('Give up on the loan', 'Unnecessary')],
        fb='A freeze can be lifted for a set time and then returns.', sub='Lifting a freeze for a loan', how=True),
    ]),
  ],
  nat=('Managing Risk', 'Identify ways to prevent identity theft and the steps to recover from it'), nj=['RM', 'CP'],
  status='time_sensitive', sources=[FTC_IDT, CFPB_CC], extra=['Using IdentityTheft.gov', 'Freezing credit'])

# ---------------------------------------------------------------- S99
S(99, 'Recognizing and avoiding scams', 'Identify common scams and their warning signs, and respond safely',
  main=[
    q('A caller says he is from the "Social Security office," your number is suspended, and you must pay today with gift cards. Which warning sign appears?', 'Demanding payment by gift card',
      [('The caller uses a polite tone of voice', 'Politeness is not a warning sign'), ('The call comes during business hours', 'Timing is not the sign'), ('The caller knows that you have a phone', 'Not a warning sign')],
      intro='Scam warning signs: a caller pretends to be from a trusted group, there is a problem or a prize, pressure to act now, and a demand to pay in a specific way (gift cards, wire transfer, cryptocurrency, or payment app). Government agencies do not demand gift cards.',
      fb='Real agencies never ask for payment by gift card.', sub='Imposter scams'),
    q('Rosa sells a bike online for $300. The buyer mails a check for $1,500 and asks her to send back $1,200 by payment app. The check bounces a week later. How much does Rosa lose?', '$1,200 plus the bike',
      [('Nothing, since the bank cleared the check', '"Available" does not mean the check is good'), ('Only the $300 bike price', 'Ignores the money she sent'), ('$1,500 but she keeps the bike', 'Misreads what she sent')],
      intro='In a fake check scam, the scammer overpays with a fake check and asks for the difference back. Banks make deposits available quickly, but the check can bounce days later and the depositor must repay the bank.',
      fb='She must repay the bank for the $1,500 check, so she loses the $1,200 she sent and the bike she shipped.', calc=1200, sub='Fake check scams'),
    q('A job posting pays $40 an hour to "reship packages" after you pay $99 for a starter kit. What is the best response?', 'Avoid it; it shows scam signs',
      [('Pay the fee because good jobs require investment', 'Real employers do not charge to hire'), ('Give your bank login so they can send pay', 'Never share logins'), ('Reship the packages to earn trust first', 'Could involve stolen goods')],
      fb='Paying to get a job and reshipping packages are classic scam signs.', sub='Job scams'),
    q('A pop-up says Rosa\'s computer has a virus and to call a number for "tech support." What should she do?', 'Close the page and not call',
      [('Call and give the support agent remote access', 'Lets scammers in'), ('Pay with a gift card for a quick fix', 'Payment red flag'), ('Share her passwords so they can test them', 'Never share passwords')],
      fb='Real tech companies do not use pop-ups with phone numbers; close it and run trusted security software.', sub='Tech support scams', how=True),
    q('Rosa was scammed. Where should she report it?', 'ReportFraud.ftc.gov',
      [('Only to the scammer, to ask for a refund', 'Will not help'), ('Nowhere, since reporting does nothing', 'Reports help stop scams'), ('A website that promises to recover money for a fee', 'Recovery scam')],
      intro='Report fraud to the FTC at ReportFraud.ftc.gov, to your bank or payment app right away, and to state agencies such as the New Jersey Division of Consumer Affairs.',
      fb='The FTC collects scam reports; contact your bank quickly too.', sub='Reporting scams', how=True),
  ],
  back=[
    concept('Payment methods and how hard they are to undo', 'Scammers choose payments that are hard to reverse.', [
      q('Which payment is hardest to get back after a scam?', 'Gift card codes',
        [('A credit card purchase you dispute', 'Dispute rights exist'), ('A check you stop in time', 'Can be stopped'), ('A debit card charge reported quickly', 'Protections exist')],
        fb='Gift card codes are like cash once shared.', sub='Hard-to-reverse payments'),
      q('Which payment gives the strongest legal protection for online shopping?', 'A credit card',
        [('A wire transfer', 'Hard to reverse'), ('Cryptocurrency', 'Hard to reverse'), ('A gift card', 'Like cash')],
        fb='Credit cards have federal dispute rights and liability limits.', sub='Protected payments'),
      q('"Act now or lose this offer!" is an example of…', 'Pressure to act quickly',
        [('Good, helpful customer service', 'Misreads pressure'), ('A legal requirement', 'Untrue'), ('A refund policy', 'Unrelated')],
        fb='Urgency pushes victims to skip checking.', sub='Pressure tactics'),
      q('A check for $1,500 pays a $300 item. How much is the overpayment?', '$1,200',
        [('$1,800', 'Adds'), ('$300', 'Gives the price'), ('$1,500', 'Gives the check amount')],
        fb='$1,500 − $300 = $1,200.', calc=1200, sub='Overpayment'),
      q('If a message says you won a prize but must pay a fee to claim it, it is probably…', 'A scam',
        [('A normal contest rule', 'Real prizes do not require fees'), ('A tax refund', 'Unrelated'), ('A loan offer', 'Unrelated')],
        fb='Paying to receive a prize is a scam sign.', sub='Prize scams'),
    ]),
    math('Solve real-world problems with rational numbers', 'Scam losses add up the money sent and the goods lost.', 'grade_7', 25),
  ],
  go=[
    deeper('Scams targeting young people', [
      q('An online friend Rosa has never met asks her to receive money and forward it. What is she being asked to do?', 'Act as a money mule',
        [('Join a legitimate savings club', 'Misreads the request'), ('Open a normal business account', 'Misreads the request'), ('Help a charity process donations', 'Misreads the request')],
        intro='Money mules move stolen money for criminals, often recruited online. It can lead to frozen accounts and criminal charges.',
        fb='Forwarding money for strangers can make you a money mule.', sub='Money mules'),
      q('A website sells sneakers worth $200 for $40 and accepts only payment apps. What is the best move?', 'Buy elsewhere',
        [('Buy several pairs to resell', 'Doubles the loss'), ('Pay with a gift card for a discount', 'Hard to reverse'), ('Send money first and check reviews later', 'Too late')],
        fb='A huge discount plus unusual payment is a red flag.', sub='Online shopping scams'),
      q('A "friend" messages from a new account asking to borrow $100 urgently. What should Rosa do?', 'Contact the friend another way to check',
        [('Send the money right away', 'Imposter risk'), ('Send half to be safe', 'Still risky'), ('Ask for the friend\'s password to verify', 'Never ask for passwords')],
        fb='Verify through a known channel before sending money.', sub='Friend imposters', how=True),
      q('Rosa paid a scammer $200 with a debit card and reports it the same day. What should she ask the bank to do?', 'Dispute the charge and block the card',
        [('Increase her credit limit', 'Unrelated'), ('Delete her account history', 'Unrelated'), ('Send more money to test it', 'Unsafe')],
        fb='Quick reporting gives the best chance of recovery.', sub='Acting fast', how=True),
      q('A "recovery service" offers to get Rosa\'s lost money back for an upfront fee. What is it likely to be?', 'Another scam',
        [('A government program', 'Government help is free'), ('A required step before reporting', 'Untrue'), ('Insurance that pays her back', 'Untrue')],
        fb='Recovery scams target people who were already scammed.', sub='Second-wave scams'),
    ]),
  ],
  nat=('Managing Risk', 'Identify common types of fraud and scams and the actions to take if victimized'), nj=['RM', 'FP'],
  status='time_sensitive', sources=[FTC_SCAMS, FTC_CHECK, NJ_DCA], extra=['Reporting fraud to the FTC', 'Spotting fake check scams'])

